SELECT p.id, p.type, p.leaf_category_id, p.title, p.completeness_level, p.status, p.status_reason, p.created_at, p.expire_at, p.version FROM post p WHERE p.user_id = #{userId}
AND p.status IN #{s}
AND ( p.status_reason IN #{r} OR p.status_reason IS NULL )
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM post p
WHERE p.user_id = #{userId}

    AND p.status IN
    #{s}


    AND (
        p.status_reason IN
        #{r}
        OR p.status_reason IS NULL
    )
